(async()=>{
  const sleep=ms=>new Promise(r=>setTimeout(r,ms));
  const meta={variant:"front",cat:"citrine",steps:[]};
  try{
    const rigs=()=>((window.GEM3D&&window.GEM3D.rigs)||[]).filter(r=>r&&r.group&&r.canvas&&r.canvas.isConnected);
    const frame=document.querySelector('.frame[data-panel="gems"]');
    const stage=document.querySelector('.frame[data-panel="gems"] [data-gem-stage]');
    // WORKAROUND (page bug, no src edit): gem-tint.js step() uses a bare T that is only declared
    // inside apply(); unqualified lookup falls through to the global, so publish it. Without this the
    // tint throws at t.t===1 and the category never commits (stone stuck mid-lerp, spin stuck).
    if(!window.T&&window.THREE)window.T=window.THREE;
    meta.tWorkaround=!!window.T;
    const pill=document.querySelector('[data-gemspec-cat="citrine"]');
    if(pill)pill.click();
    const snap=()=>{let n=0;rigs().forEach(r=>{if(r.tint&&window.GEM_TINT&&window.GEM_TINT.step){try{window.GEM_TINT.step(r,5);n++;}catch(e){}}});return n;};
    for(let i=0;i<40;i++){const a=snap();if(!rigs().some(r=>r.tint))break;if(!a)await sleep(50);}
    meta.tintLeft=rigs().some(r=>r.tint);
    meta.steps.push('cat:citrine'+(pill?':click':':nopill')+':tintLeft='+meta.tintLeft);
    let c=document.querySelector('.frame[data-panel="gems"] canvas[data-gem="citrine"]')||document.querySelector('.frame[data-panel="gems"] canvas[data-gem]');
    if(c){c.style.flex='0 0 auto';c.style.height='223px';}
    await sleep(300);

    const rs=rigs();
    rs.forEach(r=>{try{r.cat.spin=0;r.t=0;r.tilt=0;r.tiltT=0;}catch(e){}});
    await sleep(600);
    rs.forEach(r=>{try{r.cat.spin=0;r.t=0;r.tilt=0;r.tiltT=0;}catch(e){}});
    const b=c?c.getBoundingClientRect():null;
    meta.canvas=c?{cw:c.clientWidth,ch:c.clientHeight,bw:Math.round(b.width),bh:Math.round(b.height),attr:c.getAttribute('width')+'x'+c.getAttribute('height'),gem:c.dataset.gem,pinned:c.style.flex+'/'+c.style.height}:null;
    meta.rigs=rs.length;
    meta.rigsFlat=(window.GEM3D&&window.GEM3D.rigs?window.GEM3D.rigs.length:0);
    meta.transmission=rs.map(r=>(r.mats&&r.mats[0]?r.mats[0].transmission:null));
    meta.bodyColor=rs.map(r=>(r.mats&&r.mats[0]&&r.mats[0].color&&r.mats[0].color.getHexString?('#'+r.mats[0].color.getHexString()):null));
    meta.catToken=rs.map(r=>(r.cat&&r.cat.token)||null);
    meta.floors=rs.map(r=>r.floors?{shadow:!!r.floors.shadow&&r.floors.shadow.visible,caustic:!!r.floors.caustic&&r.floors.caustic.visible}:null);
    meta.groupVisible=rs.map(r=>r.group.visible);
    meta.rotationY=rs.map(r=>+r.group.rotation.y.toFixed(4));
    meta.pose=rs.map(r=>({t:+(r.t||0).toFixed(3),tilt:+(r.tilt||0).toFixed(4)}));
    meta.theme=stage?stage.dataset.theme:null;
    meta.frameHidden=frame?frame.hidden:null;
    meta.bgClass=rs.map(r=>r.scene&&r.scene.background?(r.scene.background.isTexture?'texture':'color'):'none');
    return JSON.stringify(meta);
  }catch(e){return JSON.stringify({variant:"front",cat:"citrine",error:String(e&&e.stack||e)});}
})()

