    meta.bodyColor=rs.map(r=>(r.mats&&r.mats[0]&&r.mats[0].color&&r.mats[0].color.getHexString?('#'+r.mats[0].color.getHexString()):null));
    meta.catToken=rs.map(r=>(r.cat&&r.cat.token)||null);
    meta.floors=rs.map(r=>r.floors?{shadow:!!r.floors.shadow&&r.floors.shadow.visible,caustic:!!r.floors.caustic&&r.floors.caustic.visible}:null);
    meta.groupVisible=rs.map(r=>r.group.visible);
    meta.rotationY=rs.map(r=>+r.group.rotation.y.toFixed(4));
    meta.pose=rs.map(r=>({t:+(r.t||0).toFixed(3),tilt:+(r.tilt||0).toFixed(4)}));
    meta.theme=stage?stage.dataset.theme:null;
    meta.frameHidden=frame?frame.hidden:null;
    meta.bgClass=rs.map(r=>r.scene&&r.scene.background?(r.scene.background.isTexture?'texture':'color'):'none');
    return JSON.stringify(meta);
  }catch(e){return JSON.stringify({variant:"noproxy",cat:"citrine",error:String(e&&e.stack||e)});}
})()
